Q: Qt State machine : Why isn&#39;t my property animation being triggered on state change? A: <p>I don't know why your solution doesn't work. This is how it works for me:</p>
<pre class="lang-cpp prettyprint-override"><code>    m_moveStateMachine = new QStateMachine(this);
    QState* idleState = new QState(m_moveStateMachine);
    QState* movingState = new QState(m_moveStateMachine);
    idleState-&gt;assignProperty(this, &quot;pos&quot;, QPoint(0, 0));
    movingState-&gt;assignProperty(this, &quot;pos&quot;, QPoint(100, 250));

    QSignalTransition* idleToMovingTransition = idleState-&gt;addTransition(
        this, &amp;MainWindow::startMovingAnimation, movingState);

    QPropertyAnimation* anim =
        new QPropertyAnimation(this, &quot;pos&quot;, m_moveStateMachine);
    anim-&gt;setDuration(1000);

    idleToMovingTransition-&gt;addAnimation(anim);

    connect(anim, &amp;QPropertyAnimation::stateChanged,
        [](QAbstractAnimation::State state) {
            qDebug() &lt;&lt; state;
        }
    );
</code></pre>
